// Public FAQ — 120 questions in seven topics. Product answers are written from the code, Terms and live rules
// (numbers come from publicFacts(), so they follow Admin → Rules & Settings). Edit here; pages update on deploy.
import type { PublicFacts } from "@/lib/public/facts";
import { usd } from "@/lib/public/facts";
import { ROUTES, SUPPORT_EMAIL } from "@/lib/public/site";

export type Faq = { id: string; q: string; a: string[]; tips?: string[]; link?: { href: string; label: string } };
export type FaqCategory = { slug: string; title: string; audience: string; intro: string; items: Faq[] };

const G = (slug: string, label: string) => ({ href: `/resources/${slug}`, label });
const P = (href: string, label: string) => ({ href, label });

export function faqCategories(f: PublicFacts): FaqCategory[] {
  const fee = usd(f.feeDollars), cap = usd(f.capDollars);
  return [
    {
      slug: "business-discovery", title: "Business discovery and free listings", audience: "Beauty and wellness professionals",
      intro: "Where to list your services, how listings differ from booking tools, and how to be easier to find.",
      items: [
        { id: "where-list-free", q: "Where can I list my beauty business for free?", a: ["Start with the free listings people already search: a Google Business Profile, Apple Business Connect, Bing Places, Yelp, and your social profiles with booking links. Add niche platforms that match your clients — for example, Nearest if you want to reach verified students in a city where it's live. Free usually means free to list; many platforms still charge card processing or per-booking fees, so read each fee page."], tips: ["Use the exact same business name, phone and service area everywhere.", "Pick two or three listings you'll keep updated rather than ten you'll forget."], link: G("where-to-list-beauty-business-free", "Where to list your beauty business for free") },
        { id: "free-advertising", q: "What are the best free ways to advertise a beauty business?", a: ["The free methods that work best are the ones that put your work in front of people who already live near you: a complete Google Business Profile, short videos of real results, referrals from happy clients, partnerships with nearby businesses, and community boards. Consistency beats volume — three posts a week for three months does more than thirty posts in one week."], link: G("get-more-beauty-clients-without-ads", "How to get more beauty clients without paying for ads") },
        { id: "nail-discovered", q: "How do I get my nail business discovered online?", a: ["Make it easy for someone searching \"nails near me\" to find you, see your work and book. Claim your Google Business Profile with the category \"Nail salon\" (or your closest fit), post clear photos of finished sets with the style named in the caption, list your prices, and put one booking link everywhere."], tips: ["Name styles the way clients search: \"short almond French tips\", not just \"new set\".", "Ask every happy client for a Google review the same day."], link: G("nail-tech-30-day-content-calendar", "30-day content calendar for nail techs") },
        { id: "hairstylist-no-ads", q: "How can hairstylists find new clients without paid ads?", a: ["Lean on people who have already seen your work: ask each client for one referral, offer a model slot for a style you want to be known for, post before-and-afters with the service and length named, and keep a waitlist so cancellations become bookings. Local partnerships — a boutique, a photographer, a dance studio — bring warm introductions instead of cold clicks."], link: G("first-10-clients-new-hairstylist", "How to get your first 10 clients as a new hairstylist") },
        { id: "lash-list", q: "Where can independent lash technicians list their services?", a: ["Lash techs usually combine a Google Business Profile, Instagram and TikTok with a booking platform that takes deposits. Add marketplaces where your ideal clients look; if you serve students in a city where Nearest is live, Nearest lets verified students find and request you. Whatever you choose, show healed results, aftercare and your refill policy clearly."], link: G("more-lash-clients-without-discounting", "How to get more lash clients without discounting") },
        { id: "braiding-no-monthly", q: "Can I list my braiding business without paying monthly fees?", a: ["Yes. Google Business Profile, Apple Business Connect, Bing Places and social profiles cost nothing to list. Some booking platforms also have free plans with per-booking or processing fees. On Nearest, new professionals list for free with no monthly membership fee; a flat service fee is added to each booking and card processing comes out of payouts."], link: P("/free-business-listing", "Compare free business listing options") },
        { id: "what-directory", q: "What is a beauty business directory?", a: ["A directory is a searchable list of businesses with basic details — name, location, services, photos, reviews and contact or booking links. Some directories only send people to your page; others let clients book and pay inside them. Directories help when they match how your clients search, and when your listing is complete and current."], link: P("/free-business-listing", "How listings compare") },
        { id: "listing-vs-booking", q: "How is a business listing different from a booking platform?", a: ["A listing helps people find you; a booking platform manages the appointment — calendar, deposits, reminders and payments. Many tools do a bit of both. You can keep one booking platform as your calendar and use several listings to bring people to it. Nearest is a student-focused marketplace: students find you and book through Nearest, and you can keep your other tools for everyone else."], link: G("where-to-list-beauty-business-free", "Where to list your business") },
        { id: "multiple-platforms", q: "Can I use multiple booking platforms at the same time?", a: ["Yes, as long as you protect yourself from double bookings. Block the same time in every calendar as soon as a booking comes in, keep your hours identical across tools, and check each platform's notifications daily. Many professionals keep one main calendar and treat other platforms as extra doors in."], tips: ["Turn on phone alerts for every platform you use.", "Pick one place to keep client notes so nothing gets lost."], link: P("/faq#nearest-alongside", "Using Nearest alongside another app") },
        { id: "easier-google", q: "How do I make my beauty services easier to find on Google?", a: ["Claim and complete your Google Business Profile, choose accurate categories, add every service with a price range, post photos regularly, and ask clients for reviews that mention the service. If you work from home or travel to clients, set a service area instead of showing your home address."], link: G("get-beauty-business-found-on-google", "How to get your beauty business found on Google") },
        { id: "home-based-safely", q: "How do I promote a home-based beauty business safely?", a: ["Promote your work, not your address. Show your neighborhood or service area publicly, share the exact address only with confirmed clients close to the appointment, take deposits, and keep messages in your booking tool. Check local zoning and licensing rules for home-based services, and have a clear policy on guests and parking."], tips: ["Use a business phone number or app messaging instead of your personal number.", "Trust your instincts — you can decline any booking."], link: G("get-more-beauty-clients-without-ads", "Growing without paid ads") },
        { id: "profile-info", q: "What information should I include in a beauty professional profile?", a: ["Clients decide quickly, so give them what they need to say yes: a clear photo of you, your business name, the services you offer with prices and how long each takes, your area, your availability, real photos of your work, and your policies (deposits, lateness, cancellations). A short bio that says who you love working with helps the right clients pick you."], link: G("improve-beauty-profile-booking-conversion", "Improve your profile and booking conversion") },
        { id: "need-website", q: "Do I need a website to market my beauty services?", a: ["Not to get started. A complete Google Business Profile, an active social profile and a booking link can carry a new business. A simple website helps later — it's yours, it can rank for searches in your area, and it gives one home for prices, policies and booking. Start with what you'll keep updated."], link: G("get-beauty-business-found-on-google", "Getting found on Google") },
        { id: "no-followers", q: "How do I promote my beauty business when I have no followers?", a: ["Followers come after usefulness. Post real work (even on friends or family, with permission), explain what you did and why, and share it where locals already are: neighborhood groups, community boards, your Google profile. Ask your first clients to tag you. A dozen people who actually book matter more than a thousand who scroll."], link: G("get-more-beauty-clients-without-ads", "Getting clients without ads") },
        { id: "not-in-search", q: "What can I do if my beauty business is not appearing in search results?", a: ["Check the basics first: is your Google Business Profile verified, are your category and service area correct, and is your name, phone and area identical everywhere? Then add services, photos and reviews, and post updates. New listings can take weeks to show up; search engines don't guarantee placement for anyone."], link: G("get-beauty-business-found-on-google", "Diagnose search visibility") },
      ],
    },
    {
      slug: "getting-clients", title: "Getting clients and improving bookings", audience: "Beauty and wellness professionals",
      intro: "Practical steps to fill your schedule, turn interest into bookings and keep clients coming back.",
      items: [
        { id: "first-10", q: "How do I get my first 10 beauty clients?", a: ["List the people who already trust you and tell them you're booking, with one clear service and price. Offer a few model or intro appointments in exchange for photos and an honest review, post every result, and ask each new client for one referral. Ten clients usually come from personal reach and referrals before they come from strangers online."], link: G("first-10-clients-new-hairstylist", "Your first 10 clients, step by step") },
        { id: "nail-more", q: "How can a nail tech get more bookings?", a: ["Make your best-selling sets easy to book: show them with names and prices, keep a few weekly openings you promote, and offer a rebook at checkout. Content that shows the process — prep, shaping, finish — builds trust. Fill quiet days with a clearly limited offer rather than a permanent discount."], link: G("nail-tech-30-day-content-calendar", "30-day nail tech content calendar") },
        { id: "new-stylist", q: "How can a new hairstylist build clientele?", a: ["Pick two or three services you want to be known for and build around them: a clear price list, before-and-afters, a referral offer and consistent availability. Work with models while you build a portfolio, ask every client to rebook before they leave, and follow up a few weeks later with a reminder."], link: G("first-10-clients-new-hairstylist", "Building clientele as a new stylist") },
        { id: "barber-regulars", q: "How can a barber attract regular clients?", a: ["Regulars come from reliability. Keep consistent hours, run on time, remember how each client likes their cut, and book their next visit before they leave. Offer a standing appointment (every two or three weeks), show fresh cuts on social media with the style named, and make it easy to book in under a minute."], link: G("get-more-beauty-clients-without-ads", "Growing without paid ads") },
        { id: "makeup-more", q: "How can a makeup artist book more appointments?", a: ["Makeup is often booked for events, so market ahead of the calendar: prom, homecoming, graduation, weddings, photo shoots and holidays. Show the same face in different lighting, list event packages with clear prices and travel details, and post your open dates early. Partner with photographers and stylists for referrals."], link: G("student-clients-prom-homecoming-graduation", "Marketing event-season appointments") },
        { id: "lash-empty", q: "How can a lash tech fill empty appointment slots?", a: ["Keep a short waitlist and message it first when a slot opens. Post openings with the exact time and service, offer a fill appointment to clients who are due, and use a deposit policy that discourages last-minute cancellations. Avoid discounting every opening — it trains clients to wait."], link: G("more-lash-clients-without-discounting", "More lash clients without discounting") },
        { id: "braider-repeat", q: "How can a braider attract repeat clients?", a: ["Make the next appointment part of the service: tell clients how long the style should last, book the takedown or next install before they leave, and share aftercare that protects their edges and scalp. Consistent pricing by size and length, and honest time estimates, build the trust that brings people back."], link: G("repeat-clients-braiding-locs", "Repeat clients for braiding and locs") },
        { id: "followers-to-bookings", q: "How do I turn social media followers into bookings?", a: ["Give followers a reason and a way to book right now: pin a post with services, prices and your booking link, end posts with one clear next step, and share specific openings. Answer DMs quickly with the link instead of long back-and-forth. Track which posts bring bookings and make more like them."], link: G("improve-beauty-profile-booking-conversion", "Turn views into bookings") },
        { id: "views-no-book", q: "Why do people view my beauty page but not book?", a: ["Usually something is missing or unclear: no prices, unclear location, no available times, too many steps, or photos that don't match the service they want. Look at your page as a stranger would and fix the first thing that would make you hesitate."], link: G("why-beauty-business-not-getting-bookings", "Diagnostic checklist: why you're not getting bookings") },
        { id: "slow", q: "What should I do when my beauty business is slow?", a: ["Use slow weeks to build demand: message past clients who are due, post your work every day that week, ask for reviews, update your listings and photos, and reach out to one local partner. Fix anything on your booking page that adds friction. A short, honest promotion is fine; a permanent price cut usually isn't."], link: G("why-beauty-business-not-getting-bookings", "What to check when bookings slow down") },
        { id: "no-shows", q: "How can I reduce no-shows and last-minute cancellations?", a: ["Take a deposit, send reminders a day before and a few hours before, and make your policy short and visible before booking. Make rescheduling easy so people move appointments instead of skipping them. Track repeat no-shows and require full prepayment for them."], tips: ["On Nearest, bookings are paid in advance and include a protected deposit that's paid to you on a late cancellation or no-show."], link: P("/faq#cancellations-refunds", "How Nearest handles cancellations") },
        { id: "rebook", q: "How do I encourage clients to rebook?", a: ["Ask before they leave and suggest a date that matches the service — \"your fill is due in about three weeks, does the 14th work?\" Explain why timing matters for results, send a friendly reminder when they're due, and thank returning clients. Rebooking is easiest while they're happy in your chair."], link: G("repeat-clients-braiding-locs", "Building repeat clients") },
        { id: "referrals", q: "How can I ask customers for referrals without sounding pushy?", a: ["Ask when the client is happiest — right after they see the result — and make it simple: \"If a friend asks who did your hair, I'd love for you to send them my way.\" Give them something easy to share (your link or a card) and thank anyone who refers, with a small credit or add-on if you choose."], link: P("/beauty-marketing-resources#referral-scripts", "Referral scripts you can copy") },
        { id: "stand-out", q: "How do I stand out in a saturated beauty market?", a: ["Be specific. Choose a style, client or occasion you want to be known for, and say it plainly in your bio, photos and services. Clients pick the professional who looks like the answer to their exact need. Reliability, cleanliness and clear communication also set you apart in a crowded market."], link: G("improve-beauty-profile-booking-conversion", "Make your profile stand out") },
        { id: "trust-new", q: "How do I build trust as a new beauty professional?", a: ["Show real work, explain your process, list your prices and policies, and be easy to reach. Share your training or license status honestly, keep your space and tools visibly clean, and collect reviews from your first clients. Small, consistent details — on-time starts, quick replies — build trust faster than claims."], link: G("first-10-clients-new-hairstylist", "Building trust from day one") },
        { id: "booking-info", q: "What booking information do clients need before scheduling?", a: ["The service name, price (and what changes it), how long it takes, where it happens, what to bring or how to prepare, your deposit and cancellation policy, and the times you're free. Missing any of these usually means a DM instead of a booking."], link: G("improve-beauty-profile-booking-conversion", "Booking-page checklist") },
        { id: "weekday-slots", q: "How do I fill weekday or after-school appointment slots?", a: ["Promote them to the people who can use them: students after classes, remote workers, parents during school hours. Name the time in your posts (\"Tuesday and Thursday 4–7 PM\"), create a quicker service that fits a short window, and offer those times first to clients who are due."], tips: ["On Nearest you can set after-school hours separately from your regular hours."], link: G("student-clients-prom-homecoming-graduation", "Attracting student clients") },
      ],
    },
    {
      slug: "marketing", title: "Marketing and content creation", audience: "Beauty and wellness professionals",
      intro: "Content plans, captions, flyers and seasonal promotions that bring bookings.",
      items: [
        { id: "content-calendar", q: "How do I create a 30-day beauty content calendar?", a: ["Pick four or five content types you can repeat — results, process, tips, behind the scenes, and a booking post — and rotate them through the month. Plan three to five posts a week, batch-film on a slower day, and leave room for real client results as they happen."], link: G("nail-tech-30-day-content-calendar", "A full 30-day calendar you can copy") },
        { id: "nail-instagram", q: "What should nail techs post on Instagram?", a: ["Clear, well-lit photos and short videos of finished sets, the shaping and application process, close-ups that show clean cuticle work, before-and-afters of repairs, and posts that show your price list and booking link. Name the shape, length and style so people searching can find you."], link: G("nail-tech-30-day-content-calendar", "30 days of nail content ideas") },
        { id: "hair-tiktok", q: "What should hairstylists post on TikTok?", a: ["Short transformations, the one step that makes a style work, honest timing (\"knotless, waist length, 6 hours\"), product and maintenance tips, and answers to questions clients ask you. Talk to the camera sometimes — people book people. End with where to book."], link: G("first-10-clients-new-hairstylist", "Getting clients as a stylist") },
        { id: "content-bookings", q: "What content helps beauty businesses get bookings?", a: ["Content that answers the questions a client has right before they book: what will it look like on someone like me, how much is it, how long does it take, how do I book, and can I trust you? Results with prices, process clips, reviews and posts about specific openings convert best."], link: G("improve-beauty-profile-booking-conversion", "Content that converts") },
        { id: "flyer-create", q: "How do I create a flyer for my beauty business?", a: ["Keep it to one main message: what you do, who it's for, one standout photo, two to four services with prices, your area, and one way to book (a short link or QR code). Use large text that's readable from a few feet away, and print only where your clients actually pass by."], link: G("beauty-business-flyer", "How to make a flyer that converts") },
        { id: "nail-flyer", q: "What should a nail business flyer include?", a: ["Your business name, a crisp photo of your best set, three signature services with prices, your neighborhood or service area, booking hours, a QR code to your booking link and, if you use one, a limited new-client offer with an end date."], link: G("beauty-business-flyer", "Sample flyer copy") },
        { id: "lash-captions", q: "What captions should a lash technician use?", a: ["Captions that name the set and the result: \"Classic set, 10–12 mm, natural cat-eye — booking refills Tuesday and Thursday.\" Add aftercare tips, answer a common question, or tell a short story about the client's event. Finish with one call to action."], link: G("more-lash-clients-without-discounting", "Lash captions you can copy") },
        { id: "referral-promo", q: "How do I create a referral promotion for beauty services?", a: ["Reward both people with something small that costs you little — a credit, a free add-on, or priority booking — and set clear rules: when it applies, how long it lasts, and that it's for new clients. Track referrals by name so you can thank people."], link: P("/beauty-marketing-resources#referral-scripts", "Referral promotion templates") },
        { id: "no-photos", q: "What should I post when I have no client photos?", a: ["Post your process on practice heads, models or yourself, your workspace setup, tool cleaning, product explanations, quick tips, and a clear price list. Short videos of you talking about what you specialize in also work. Label practice work honestly."], link: G("get-more-beauty-clients-without-ads", "Content when you're starting out") },
        { id: "openings-not-desperate", q: "How do I promote openings without looking desperate?", a: ["Present openings as information, not a plea: \"Two spots open Thursday after 4 for silk presses.\" Post them on a regular rhythm, send them to your waitlist first, and keep prices steady. Clients read regular, specific posts as a busy professional being organized."], link: G("more-lash-clients-without-discounting", "Filling openings without discounting") },
        { id: "prom", q: "How do I market prom makeup or hair appointments?", a: ["Start four to eight weeks before local prom dates. Share looks for different outfits and skin tones, list a prom package with timing and price, offer trials, and post how many spots you have left. Make sure your policies for minors (parental consent, who can attend) are clear."], link: G("student-clients-prom-homecoming-graduation", "Prom, homecoming and graduation marketing") },
        { id: "back-to-school", q: "How do I market back-to-school grooming services?", a: ["Promote two to three weeks before classes start with fresh cuts, braids, nails and brows that hold up through the first weeks. Offer after-school and weekend slots, show styles that are low-maintenance, and remind parents and students to book early."], link: G("student-clients-prom-homecoming-graduation", "Student seasons calendar") },
        { id: "homecoming", q: "What are effective homecoming beauty promotion ideas?", a: ["Bundle services friends can book together, post looks that match school colors, offer group time slots, and share a simple timeline so students know when to book. Advertise early and say clearly how many appointments you can take."], link: G("student-clients-prom-homecoming-graduation", "Event-season promotion ideas") },
        { id: "graduation", q: "How do I plan graduation-season beauty promotions?", a: ["Graduation week fills fast. Announce availability a month ahead, offer photo-ready packages, and coordinate timing with ceremony schedules. Look for families booking several people and offer back-to-back slots."], link: G("student-clients-prom-homecoming-graduation", "Graduation-season planning") },
        { id: "seasonal-budget", q: "How do I market seasonal services on a small budget?", a: ["Reuse what works: one good photo shoot can supply weeks of posts. Promote early, focus on a single seasonal offer, use free listings and community boards, and partner with a local business for cross-promotion. Measure which channel brings bookings before you spend anything."], link: G("get-more-beauty-clients-without-ads", "Low-budget growth") },
        { id: "insta-tiktok-google", q: "Should beauty professionals focus on Instagram, TikTok, or Google?", a: ["Go where your clients look when they're ready to book. Google captures people searching right now; Instagram is where many check your work and book; TikTok can reach new people quickly. Most professionals do best with a complete Google profile plus one social platform they post on consistently."], link: G("get-beauty-business-found-on-google", "Getting found on Google") },
        { id: "bio", q: "How do I write a professional bio that gets bookings?", a: ["Say who you are, what you specialize in, who you love working with and how to book — in two or three sentences. Mention your experience honestly and one detail that makes clients comfortable. Avoid lists of every service; your services section does that."], tips: ["Example: \"Hi, I'm Dani — I specialize in knotless braids and boho styles for school and events. I keep appointments on time and walk you through aftercare. Book below.\""], link: G("improve-beauty-profile-booking-conversion", "Profile and bio checklist") },
        { id: "marketing-plan", q: "How do I build a simple marketing plan for my beauty business?", a: ["Write down your ideal client, two or three services to promote, the channels you'll use, how often you'll post, and one number to track (new bookings per week). Review it monthly, keep what works and drop what doesn't."], link: P("/grow-your-beauty-business", "Grow your beauty business") },
      ],
    },
    {
      slug: "pricing-operations", title: "Pricing, operations and growth", audience: "Beauty and wellness professionals",
      intro: "Pricing for students, profit per appointment, policies and growing at a pace you can keep.",
      items: [
        { id: "price-students", q: "How should I price beauty services for students?", a: ["Start from your real cost and time, then design student-friendly options instead of cutting your main price: shorter services, simpler styles, off-peak times or smaller sets. Make sure every option still pays you fairly per hour."], link: G("price-student-friendly-beauty-services", "Pricing student-friendly services profitably") },
        { id: "student-discount", q: "How do I offer student discounts without losing money?", a: ["Limit the discount to specific services or times you need to fill, set a clear end date or cap, and check your profit per appointment after the discount. A dedicated student menu is often better than a percentage off everything."], link: G("price-student-friendly-beauty-services", "Student pricing without losing money") },
        { id: "profit-per-appt", q: "How do I calculate profit per appointment?", a: ["Take the price, subtract product and supply cost, platform and card-processing fees, travel cost and a share of fixed costs (rent, tools, insurance), then divide what's left by the hours you spent, including setup and cleanup. That hourly number tells you which services to promote."], link: G("price-student-friendly-beauty-services", "Profit-per-appointment worksheet") },
        { id: "duration", q: "How do I set service duration and availability?", a: ["Time yourself on real appointments, add buffer for consultation and cleanup, and round up. Set availability you can keep every week. Clients trust a calendar that stays the same more than one that keeps changing."], link: G("improve-beauty-profile-booking-conversion", "Booking setup checklist") },
        { id: "which-promote", q: "How do I decide which services to promote first?", a: ["Promote services that are profitable per hour, that you enjoy, and that lead to repeat visits. A service clients come back for every few weeks is worth more over time than a one-off."], link: G("price-student-friendly-beauty-services", "Choosing what to promote") },
        { id: "cancel-policy", q: "What is a good cancellation policy for beauty professionals?", a: ["A good policy is short, fair and enforced the same way for everyone: a deposit, a notice period (often 24–48 hours), what happens to the deposit, and how lateness is handled. Show it before booking and remind clients in your confirmation."], link: P("/faq#cancellations-refunds", "How Nearest's cancellation rules work") },
        { id: "more-profitable", q: "How do I make my beauty business more profitable?", a: ["Raise prices on in-demand services, add optional add-ons, reduce gaps between appointments, rebook clients before they leave, and cut products or platforms you don't use. Track profit per hour by service."], link: G("price-student-friendly-beauty-services", "Profitability basics") },
        { id: "no-salon", q: "How do I grow without opening a salon?", a: ["Grow your client base, raise prices as demand builds, add services that pair with what you do, and consider suite rental or mobile services before a full salon. Many independent professionals build full schedules from a home studio or suite."], link: P("/grow-your-beauty-business", "Growing as an independent professional") },
        { id: "platform-pros-cons", q: "What are the pros and cons of booking platforms?", a: ["Pros: online booking around the clock, deposits, reminders, payment handling and sometimes new clients. Cons: fees, less control over the client relationship, and another place to manage. Choose based on what you need most."], link: P("/free-business-listing", "Comparing listing and booking options") },
        { id: "choose-platform", q: "How do I choose a booking platform for my beauty business?", a: ["List what you need — deposits, reminders, client notes, payouts, a free tier — and what you'll pay per month and per booking. Try one with real clients for a month."], tips: ["Ask: who owns the client list, how do refunds work, how long do payouts take?"], link: P("/free-business-listing", "Choosing where to list and book") },
        { id: "part-time", q: "Can I grow a beauty business part time?", a: ["Yes. Pick fixed days and hours you can protect, focus on two or three services, and use a booking tool so clients can book without waiting for you to reply."], link: P("/grow-your-beauty-business", "Sustainable growth") },
        { id: "manageable-schedule", q: "How do I keep my schedule manageable while growing?", a: ["Set a maximum number of appointments per day, build in breaks and buffer time, block admin time each week, and raise prices before you add hours."], link: P("/grow-your-beauty-business", "Growing at a pace you can keep") },
        { id: "student-boundaries", q: "How can I serve students while maintaining professional boundaries?", a: ["Keep all communication about the appointment in your booking tool, be clear and consistent about policies, keep appointments to the service booked, and don't connect with young clients on personal social media."], link: G("student-clients-prom-homecoming-graduation", "Serving student clients professionally") },
        { id: "minors-safety", q: "What safety practices matter when serving minors?", a: ["Follow your state's licensing rules and any parental-consent requirements for the service, keep communication in the booking platform, keep the door open or a parent welcome, and never offer services that require an adult client. This is general guidance, not legal advice."], tips: ["On Nearest, services marked 18+ only can't be booked by students under 18, and students 13–17 need a parent or guardian's approval to book."], link: P("/faq#safety-privacy", "How Nearest handles safety") },
      ],
    },
    {
      slug: "for-professionals", title: "Nearest for professionals", audience: "Professionals considering Nearest",
      intro: "How listing on Nearest works — written from the platform's current rules.",
      items: [
        { id: "what-is-nearest", q: "What is Nearest?", a: ["Nearest — Student Beauty, Wellness & Self-Care Booking Platform — is an online marketplace at usenearest.com that connects high school, college, trade school and online students with independent beauty, grooming, wellness and self-care professionals near them. Students already get discounts on food, clothing, tech and entertainment; Nearest exists so self-care can be student-priced too. Bookings are available in cities where professionals are live."], link: P("/about-nearest", "About Nearest") },
        { id: "is-booking-platform", q: "Is Nearest a beauty booking platform?", a: ["Yes — a student-focused one. Students book and pay through Nearest; professionals set their own services, prices and hours. Nearest isn't a general directory for everyone: it serves verified students, and only in cities where it's live."], link: P("/for-professionals", "How Nearest works for professionals") },
        { id: "who-can-join", q: "Who can join Nearest as a professional?", a: ["Independent professionals who are at least 18, legally able to work in the U.S., and hold any license or permit their services require. You verify your identity with a government ID and a live selfie reviewed by Nearest, and you report your professional status yourself. Spots are limited per city and category."], link: P("/for-professionals", "Eligibility and how to join") },
        { id: "free-to-list", q: "Is it free to list my business on Nearest?", a: [`Yes for new professionals: no sign-up fee, no monthly membership fee and no card needed. Nearest earns a flat service fee (currently ${fee}) on each service and Model Call booked; by default it's added to your price so you receive your full price. Card-processing fees come out of each payout.`], link: P("/for-professionals#fees", "Fees, explained") },
        { id: "monthly-fees", q: "Does Nearest charge professionals monthly fees?", a: [`No. There's no monthly membership fee. Nearest's revenue is the service fee on completed bookings (currently ${fee}). Professionals who had an earlier membership were moved to the no-fee model.`], link: P("/for-professionals#fees", "How Nearest earns") },
        { id: "replace-platform", q: "Does Nearest replace my current booking platform?", a: ["No. Nearest is designed to work alongside the tools you already use. Students who find you on Nearest book through Nearest; your other clients keep booking the way they do now. Block time across your calendars so you don't double-book."], link: P("/faq#nearest-alongside", "Using Nearest with another app") },
        { id: "how-register", q: "How do I register as a professional on Nearest?", a: ["Create an account at the professional sign-up page, then build your profile step by step: profile and photos, services and prices, professional status, location and travel, hours, communication, and identity verification. On the last step you read and accept the Professional Terms and submit for review."], link: P(ROUTES.proSignUp, "Join as a professional") },
        { id: "help-create-profile", q: "Can Nearest help create my professional profile with permission?", a: ["Yes. With your permission, someone on the Nearest team can set up your profile from details you share. You receive an email link, create your own password, review your profile and accept the Professional Terms before it goes live. After that, it's your account."], link: P("/for-professionals#profile-help", "Profile setup help") },
        { id: "services-list", q: "What services can professionals list on Nearest?", a: [`Categories currently include ${f.categories.join(", ")}. Within each category you list your own services, prices, durations and optional add-ons. Services that legally require an adult client can be marked 18+ only.`], link: P("/for-professionals#services", "Service categories") },
        { id: "student-pricing-required", q: "Do professionals need to offer student-friendly pricing?", a: [`Nearest is a student marketplace, so no service can cost students more than ${cap}, including add-ons. Within that limit you set your own prices. Travel fees are separate when you go to the student.`], link: G("price-student-friendly-beauty-services", "Pricing student-friendly services") },
        { id: "price-limits", q: "Are there price limits for certain services?", a: [`Yes. The current limit is ${cap} per service, add-ons included, and it applies to every category. A travel fee is added only when you travel. Any category-specific limit would be shown in the app when you set prices.`], link: P("/for-professionals#fees", "Pricing rules") },
        { id: "city-capacity", q: "How does city enrollment capacity work?", a: [`It's the same in every city and state: each service category opens with ${f.firstInPerCategory} professional spots. When they're taken, enrollment closes for that category in that city. Nearest may authorize one more opening of ${f.capPerCategory - f.firstInPerCategory} later — never more than ${f.capPerCategory} professionals per category per city.`], link: P("/for-professionals#capacity", "Capacity, explained") },
        { id: "city-full", q: "What if enrollment in my city is full?", a: ["Join the waitlist for your city and category. Enrollment doesn't reopen automatically; if Nearest authorizes the additional opening, or a spot is released, people on the waitlist are told first. A reopening isn't guaranteed."], link: P("/for-professionals#capacity", "Capacity and the waitlist") },
        { id: "which-cities", q: "What cities or states currently have Nearest?", a: ["Nearest is building nationwide, city by city. A city is live for student bookings once professionals there are approved and live. The Locations page lists those cities from the platform, and its city checker shows whether a city is live, open for professionals, closed in a category, or not open yet."], link: P("/locations", "Check a city") },
        { id: "join-before-launch", q: "Can I join before Nearest launches in my city?", a: ["Yes, wherever Nearest has opened professional enrollment for your city — you can build your profile and go live there before students start booking. If your city isn't open yet, leave your details with the city checker and Nearest can contact you when it opens. Being able to join doesn't mean students are already booking there."], link: P("/locations#check", "Check your city") },
        { id: "guarantee", q: "Does listing guarantee clients or bookings?", a: ["No. Nearest gives you a place to be discovered by verified students in your city. Bookings depend on demand, your profile, prices and availability. Nearest doesn't promise bookings, income or search placement."], link: G("improve-beauty-profile-booking-conversion", "Improve your booking conversion") },
        { id: "approvals", q: "How do appointment approvals work?", a: [`Every booking starts as a request. You get a notification, an email and — if you turn them on — phone alerts. You accept or decline within ${f.requestHours} hours (or by 2 hours before the start). After you accept, the student pays to confirm.`], link: P("/for-professionals#how-booking-works", "How booking works") },
        { id: "payments-pros", q: "How do professionals receive payments?", a: ["Payouts go through Stripe Connect to the account you connect. The student pays in full when they confirm; Nearest's processor holds it and releases it to you when the appointment is finished. Card-processing fees are deducted from payouts."], link: P("/for-professionals#fees", "Payouts and fees") },
        { id: "insurance", q: "Are there professional insurance options?", a: ["Nearest's Terms require professionals to carry professional liability and general liability insurance appropriate to their services. Nearest doesn't sell insurance; it's exploring options with a future licensed partner and asks professionals about their interest."], link: P(ROUTES.terms, "Read the Terms") },
        { id: "credentials", q: "What credentials or training status can professionals indicate?", a: ["Professionals choose one status: licensed, license pending, currently enrolled, or self-taught. It's self-reported — Nearest doesn't verify licenses — and each professional is responsible for holding every license their services require."], link: P("/for-professionals#eligibility", "Eligibility") },
        { id: "school-property", q: "Can professionals serve students without going onto school property?", a: ["Yes — that's how Nearest works. Appointments happen at the professional's location or at an address the student provides. Nearest doesn't schedule services at schools and has no school partnerships or access to school property."], link: P("/faq#safety-privacy", "Safety and privacy") },
        { id: "safety-privacy", q: "How does Nearest protect privacy and safety?", a: [`Students are verified, professionals' identities are checked, phone numbers and emails aren't shared between users, messages stay in the app, and appointment addresses are shared only from 12:00 AM on the appointment day. Check-in requires being within ${f.checkinFeet} feet.`], link: P(ROUTES.privacy, "Privacy Policy") },
        { id: "contact-support", q: "How do I contact Nearest support?", a: [`Email ${SUPPORT_EMAIL}. Signed-in users can also report a problem from inside the app.`], link: P("/contact", "Contact Nearest") },
        { id: "update-profile", q: "How do I update my Nearest profile?", a: ["Sign in, open Business, and edit any step — photos, services, prices, location, hours and more. You can also go offline from Today whenever you need a break."], link: P(ROUTES.proSignIn, "Professional sign in") },
      ],
    },
    {
      slug: "students-parents", title: "Students and parents", audience: "Students and their families",
      intro: "How students find professionals, book, pay and stay safe on Nearest.",
      items: [
        { id: "affordable-students", q: "How can students find affordable beauty services?", a: ["Compare prices before you book, ask about simpler versions of styles, book off-peak times, and look for professionals who offer student-friendly menus or practice appointments with clear expectations. On Nearest, every price students see includes the service fee."], link: G("save-on-beauty-and-grooming-as-a-student", "How students can save on beauty and grooming") },
        { id: "prom-book", q: "Where can students book prom hair and makeup?", a: ["Book early — four to six weeks ahead — with someone whose past event work you like. Ask about a trial, timing on the day, and what's included. On Nearest, verified students in live cities can browse professionals, see prices and request a time."], link: G("prom-homecoming-beauty-budget", "Prom and homecoming budget planner") },
        { id: "affordable-nails", q: "How can students find affordable nail appointments?", a: ["Choose shorter lengths or simpler designs, compare prices for the same set, and book weekday or after-school times. Look at photos of the exact style you want and ask what changes the price."], link: G("save-on-beauty-and-grooming-as-a-student", "Ways to save as a student") },
        { id: "haircuts", q: "Where can students book haircuts or barber services?", a: ["Look for a barber or stylist whose recent cuts match what you want, with clear prices and times that fit your schedule. On Nearest, the Barber and Hair categories show professionals live in your area."], link: G("student-grooming-on-a-budget", "Student grooming on a budget") },
        { id: "graduation-book", q: "How do students find graduation beauty appointments?", a: ["Graduation week fills fast, so book a month ahead, confirm timing around your ceremony and photos, and ask if family or friends can book back-to-back."], link: P("/student-beauty-services#events", "Event planning tips") },
        { id: "services-available", q: "What services are available on Nearest?", a: [`Professionals list services in categories including ${f.categories.slice(0, 10).join(", ")} and more. What's available depends on which professionals are live in your city.`], link: P("/locations", "See what's live near you") },
        { id: "create-account", q: "How do students create a Nearest account?", a: ["Sign up, then verify you're a current student with a school ID photo and a selfie, proof of enrollment if your school doesn't issue IDs, or a code sent to your school email. Students 13–17 also need a parent or guardian to approve from an email Nearest sends them."], link: P(ROUTES.studentSignUp, "Create a student account") },
        { id: "how-booking", q: "How does booking on Nearest work?", a: [`Pick a professional, service and time, and send a request — you aren't charged yet. The professional accepts (or declines). Once accepted, you pay within ${f.payHours} hours to confirm. Standard bookings must be at least ${f.advanceHours} hours ahead; same-day bookings are possible only for posted openings.`], link: P("/student-beauty-services#how-booking-works", "Booking, step by step") },
        { id: "student-pricing-how", q: "How does student-friendly pricing work?", a: [`Professionals set their own prices, and no service on Nearest can cost more than ${cap}, including add-ons. Some professionals also post Model Calls — discounted appointments where they practice a technique or build a portfolio.`], link: P("/student-beauty-services", "Student-friendly pricing") },
        { id: "booking-fee", q: "Does Nearest charge students a booking fee?", a: [`There's no separate booking fee at checkout. The price you see includes Nearest's service fee (currently ${fee} per service), so the total you see is what you pay.`], link: P(ROUTES.terms, "Payments in the Terms") },
        { id: "when-pay", q: "When do students pay for appointments?", a: [`After the professional accepts your request. You then have ${f.payHours} hours (or until 1 hour before the start) to pay in full. Your payment is held until you complete the appointment's finish steps, then released to the professional.`], link: P("/student-beauty-services#how-booking-works", "Payment timing") },
        { id: "see-nearby", q: "How can students see available professionals near them?", a: ["After you sign in, Explore shows professionals live in your area, with filters for service and price. You can also search a ZIP code or nearby city."], link: P("/locations", "Cities where Nearest is live") },
        { id: "in-my-city", q: "Is Nearest available in my city?", a: ["Use the city checker on the Locations page. It shows whether students can book there now. If not, you can ask to be told when it opens — Nearest is growing nationwide, but only cities with live professionals have bookable appointments."], link: P("/locations#check", "Check your city") },
        { id: "parents-help", q: "Can parents or guardians help with booking?", a: ["Yes. Students book from their own verified account, and for students 13–17 a parent or guardian must approve the account from an email before the student can book. Parents are responsible for payments on a minor's account."], link: G("parents-guide-teen-beauty-appointments", "A parent's guide to teen appointments") },
        { id: "declined", q: "What happens if a professional declines a booking?", a: ["You're told right away and you aren't charged, because you haven't paid yet. Pick another time or professional. If nobody answers in time, the request expires the same way, with no charge."], link: P("/student-beauty-services#how-booking-works", "How requests work") },
        { id: "addresses-safety", q: "How are appointments and addresses handled safely?", a: [`The appointment address is shared only with the booked student (or, for travel appointments, the professional) starting at 12:00 AM Central Time on the appointment day. Messages stay in the app. At the appointment, you check in within ${f.checkinFeet} feet.`], link: P("/faq#safety-privacy", "Safety and privacy") },
        { id: "before-appt", q: "What should students do before an appointment?", a: ["Read the service details and any preparation notes, tell your professional about allergies or sensitivities, plan to arrive on time, and keep messages in the app."], link: P("/student-beauty-services", "Appointment tips") },
        { id: "cancellations-refunds", q: "How do refunds or cancellations work?", a: [`Nearest uses credits instead of cash refunds. Cancel ${f.cancelHours} hours or more ahead and the full amount becomes credit with that professional. Cancel later, or miss the appointment, and the ${usd(f.depositDollars)} protected deposit goes to the professional while the rest becomes credit. If a professional cancels, you get the full amount as general credit.`], link: P(ROUTES.terms, "Section 7 of the Terms") },
        { id: "school-affiliation", q: "Is Nearest affiliated with a school or school district?", a: ["No. Nearest is an independent company. It verifies that users are students, but it isn't affiliated with, endorsed by or partnered with any school or school district."], link: P("/about-nearest", "About Nearest") },
        { id: "none-nearby", q: "What if no professionals are listed nearby?", a: ["Nearest may not be live in your area yet. Try a nearby city or ZIP code, or use the city checker to ask to be told when it opens. If you know a great local professional, tell them about the professional sign-up — every city needs its first five."], link: P("/locations#check", "Check your city") },
      ],
    },
    {
      slug: "about-the-brand", title: "About Nearest and comparisons", audience: "Everyone",
      intro: "What Nearest is, how to find the official site, and how it compares with other options.",
      items: [
        { id: "student-app", q: "What is the Nearest student booking app?", a: ["It's the student side of Nearest: an installable web app at usenearest.com where verified students find independent beauty and wellness professionals near them and request, pay for and complete appointments. It installs from the browser — no app store needed."], link: P("/student-beauty-services", "Nearest for students") },
        { id: "usenearest", q: "What is usenearest.com?", a: ["usenearest.com is the official website and web app of Nearest, the student beauty, wellness and self-care booking platform. Students and professionals sign in there, and this resource center lives there too."], link: P("/about-nearest", "About Nearest") },
        { id: "official-site", q: "How do I find the official Nearest website?", a: ["Go to https://www.usenearest.com. When searching, look for \"Nearest beauty booking\" or \"usenearest\" — the word \"nearest\" on its own returns unrelated results. Nearest's official Instagram is @usenearest."], link: P("/about-nearest", "Official details") },
        { id: "students-or-pros", q: "Is Nearest for students or beauty professionals?", a: ["Both. Verified students book appointments; independent professionals list their services to reach those students. Each has its own sign-up: students at usenearest.com, professionals at usenearest.com/pro."], link: P("/for-professionals", "For professionals") },
        { id: "vs-directory", q: "What makes Nearest different from a general beauty directory?", a: ["A general directory lists everyone for everyone. Nearest is built for one audience — verified students — with prices capped for students, booking and payment inside the app, verified identities and safety rules around addresses and messages."], link: P("/free-business-listing", "How listing options compare") },
        { id: "nearest-alongside", q: "Can Nearest be used alongside another booking app?", a: ["Yes. Nearest doesn't require you to leave your current booking platform. Keep your calendars in sync by blocking time when a booking comes in from any source."], link: P("/for-professionals", "Nearest for professionals") },
        { id: "help-independent", q: "How does Nearest help independent beauty professionals?", a: ["It gives independent professionals a free place to be found by verified students in their city, with requests, payments, reminders and appointment-day tools handled in one app. It's a discovery channel, not a guarantee of bookings."], link: P("/for-professionals", "How it works") },
        { id: "any-state", q: "Can professionals from any US state apply to join Nearest?", a: ["Yes. Professionals anywhere in the U.S. can register their interest, and can enroll wherever Nearest has opened their city. Each city opens every service category with a limited number of spots, so availability depends on your city and service — not your state."], link: P("/for-professionals", "How joining works") },
        { id: "accepting-my-city", q: "How do I find out whether Nearest is accepting professionals in my city?", a: ["Search your city or ZIP code in the city checker on the Locations page. It tells you whether enrollment is open in your city and category, closed because the spots are taken, or not open yet — and lets you leave your details so Nearest can contact you if that changes."], link: P("/locations#check", "Check your city") },
        { id: "free-vs-paid", q: "What is the difference between a free listing and a paid advertisement?", a: ["A free listing is a profile people can find when they search or browse. A paid advertisement buys extra placement for a set time and stops when you stop paying. Listings build lasting visibility; ads buy short bursts."], link: P("/free-business-listing", "Free listings vs ads") },
        { id: "right-platform", q: "How do I know whether a beauty platform is right for my business?", a: ["Check who uses it, whether it's active in your area, what it costs per month and per booking, how payouts and refunds work, and whether it fits your services. Try it for a set period and count the bookings it brings."], link: P("/free-business-listing", "Evaluating platforms") },
        { id: "get-started", q: "How can I get started with Nearest today?", a: ["Professionals: create an account at the professional sign-up and build your profile. Students: create an account at usenearest.com and verify you're a student. Check Locations first to see where Nearest is live."], link: P("/locations", "Check locations, then sign up") },
      ],
    },
  ];
}
